    [Fact]
    public void EmptyBehaviourAndWrapAround()
    {
        var q = new MyCircularQueue(2);
        Assert.True(q.IsEmpty());
        Assert.False(q.DeQueue());
        Assert.Equal(-1, q.Front());
        Assert.Equal(-1, q.Rear());
        for (var i = 0; i < 10; i++)
